// Built-in sample files (embedded as base64; loaded through the real MIDI parser / audio decoder)
const SAMPLE_MIDI_NAME = "Liebestraum No.3 — Liszt";
const SAMPLE_AUDIO_NAME = "Liebestraum No.3 (Liszt) — 1 min preview";
const SAMPLE_IMAGE_NAME = "Les Amoureux — Marc Chagall";
const SAMPLE_IMAGE_MFI_NAME = "Le Rêve — Pablo Picasso";
const SAMPLE_SCORE_NAME = "Liebestraum No.3 — Liszt (MusicXML)";
const SAMPLE_SCORE_B64 = "";
const SAMPLE_IMAGE_B64_URL = "/samples/sample-image.jpg";
const SAMPLE_IMAGE_MFI_B64_URL = "/samples/sample-mfi.jpg";
const SAMPLE_MIDI_B64 = "";
const SAMPLE_AUDIO_B64_URL = "/samples/sample-audio.mp3";
function b64ToArrayBuffer(b64){
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for(let i=0;i<len;i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}

// ── Lazy sample loaders ──────────────────────────────────────────────────────
// The three largest built-in samples (audio, scan image, MFI image) used to be
// inlined as ~2MB of base64 here, bloating the initial bundle for everyone even
// though only users who tap a "sample" import ever need them. They now live as
// real files in /public/samples and are fetched on demand. Small offline-critical
// samples (onboarding MIDI, score) stay inlined. Each loader is cached after first
// fetch so a repeat tap is instant and offline-OK once warmed.
const _sampleCache = {};
async function _fetchSampleArrayBuffer(url){
  if(_sampleCache[url]) return _sampleCache[url];
  const r = await fetch(url);
  if(!r.ok) throw new Error('sample fetch '+r.status);
  const buf = await r.arrayBuffer();
  _sampleCache[url] = buf;
  return buf;
}
async function _fetchSampleDataUrl(url){
  const key = url+'#dataurl';
  if(_sampleCache[key]) return _sampleCache[key];
  const r = await fetch(url);
  if(!r.ok) throw new Error('sample fetch '+r.status);
  const blob = await r.blob();
  const dataUrl = await new Promise((res,rej)=>{ const fr=new FileReader(); fr.onload=()=>res(fr.result); fr.onerror=()=>rej(new Error('sample read')); fr.readAsDataURL(blob); });
  _sampleCache[key] = dataUrl;
  return dataUrl;
}



